\section{Introduction}

\subsection{The phenomenon}
Consider an experimental programme that summarises each run by a rank correlation between a
predictor and a response, and that has pre-registered a threshold: the effect is declared present
if the pooled correlation reaches $0.550$. Suppose the pooled reading comes back as $0.558$, with a
resampling confidence interval that straddles the floor. The recorded verdict --- \emph{approaching,
not crossed} --- is a statement of genuine ambiguity, and the standard remedy is replication.

We show that in a precise and quantifiable sense the remedy cannot work, for a class of statistics
that includes essentially all the ones an experimentalist would compute. The obstruction is not
statistical but geometric, and it is invisible to sample-size calculations because the governing
bound contains no sample size.

\subsection{The mechanism}
Correlation is scale-invariant, so a predictor is only ever seen through its direction, a point on
the unit sphere $S^{n-1}$. Two hypotheses are realised by directions $\uh,\vh$. If those directions
can be aligned to correlation $1-\varepsilon$, the identity $\|\uh-\vh\|^2 = 2-2\corr(u,v)$ places
both inside a spherical cap of radius $\sqrt{2\varepsilon}$. Any stable --- Lipschitz on the sphere
--- statistic assigns the two hypotheses values differing by at most (Lipschitz constant) times
(cap radius). Since correlation is invariant under replication, so is the cap radius, so
replication does not shrink the bound. The only way out is to abandon stability.

\subsection{Contributions}
\begin{enumerate}
\item Chordal geometry of a correlation cap (\S3): the identity $\|\uh-\vh\|^2 = 2-2c$, the cap
bound $\sqrt{2\varepsilon}$, the angular form $\arccos c \le (\pi/2)\sqrt{2-2c}$, and the fact that
alignment $0.9999$ gives angular radius below $0.9^\circ$.
\item The sample-size-free ceiling (\S4), its converse, and the specialisation $L \ge 70$ for full
separation at $\varepsilon = 10^{-4}$.
\item Exact replication invariance (\S5), hence an identical ceiling in every dimension $mn$.
\item Sharpness and non-vacuity (\S6).
\item The alignment window $[0.9999,\,0.999968]$ (\S7).
\item The optimal smooth test: correlation against the contrast direction (\S8).
\item Cap capacity and H\"older robustness (\S9).
\item The discontinuous escape (\S10).
\end{enumerate}

\section{Setting and definitions}

Throughout, $n \ge 1$ and vectors are elements of $\R^n$ regarded as coordinate tuples.

\begin{definition}[Inner product and norm]
$\langle u,v\rangle = \sum_{i=1}^n u_i v_i$ and $\|u\| = \sqrt{\langle u,u\rangle}$.
\end{definition}

\begin{definition}[Correlation]
For $u,v$ with $\|u\|,\|v\|\neq0$, $\corr(u,v) = \langle u,v\rangle/(\|u\|\|v\|)$. By
Cauchy--Schwarz, $-1 \le \corr(u,v) \le 1$. In applications $u,v$ are centred, or are rank vectors,
so that this coincides with the Pearson or Spearman coefficient; nothing below uses centring.
\end{definition}

\begin{definition}[Direction]
$\uh = u/\|u\|$, with $\hat0 = 0$. For $u \ne 0$, $\|\uh\| = 1$, $\langle\uh,\vh\rangle =
\corr(u,v)$, and $\corr(\uh,w) = \corr(u,w)$.
\end{definition}

\begin{definition}[Chordal distance]
For nonzero $u,v$, $\chord(u,v) = \|\uh-\vh\|$.
\end{definition}

\begin{definition}[Test statistic and separation]
A \emph{statistic} is a function $F : \R^n \to \R$; its \emph{separation} on $(u,v)$ is
$|F(\uh)-F(\vh)|$. It \emph{fully separates} the pair if the separation is $1$, the natural
normalisation for a decision rule valued in $\{0,1\}$.
\end{definition}

\begin{definition}[Lipschitz classes]
For $L\ge0$, $F$ is \emph{$L$-Lipschitz} if $|F(x)-F(y)| \le L\|x-y\|$ for all $x,y\in\R^n$, and
\emph{$L$-Lipschitz on the sphere} if this holds for all $x,y$ with $\|x\|=\|y\|=1$. The second
class strictly contains the first and is the one the geometry requires.
\end{definition}

\begin{definition}[H\"older on the sphere]
For $C,\alpha \ge 0$, $F$ is $(C,\alpha)$-H\"older on the sphere if $|F(x)-F(y)| \le C\|x-y\|^\alpha$
for all unit $x,y$. Exponent $\alpha=1$ recovers the Lipschitz class exactly.
\end{definition}

\begin{definition}[Replication]
For $m \ge 1$, $\rep_m(u) \in \R^{mn}$ is the concatenation of $m$ copies of $u$: the model of $m$
independent repetitions of the same experiment.
\end{definition}

\begin{definition}[Contrast direction]
For $\uh \ne \vh$, $e(u,v) = (\uh-\vh)/\|\uh-\vh\|$.
\end{definition}

\begin{definition}[Rank/threshold statistic]
For a response $w$ and cut $t\in\R$, $\Thr_{w,t}(x) = 1$ if $\corr(x,w) \ge t$ and $0$ otherwise.
\end{definition}

\begin{configuration}[The reference instance (R)]\label{cfg:R}
There exist nonzero $u,v,w \in \R^2$ with
\[
\corr(u,w) = 0.558, \qquad \corr(v,w) = 0.550, \qquad \corr(u,v) \ge 0.9999 .
\]
\end{configuration}

Configuration~\ref{cfg:R} encodes the empirical situation: $u$ realises the ``crossed'' reading, $v$
the ``exactly at the floor'' reading, $w$ is the common response, the recorded margin is
$\delta = 0.008$, and the two competing predictors can be made mutually indistinguishable to four
nines. Every numerical claim below refers to (R), i.e.\ to $\varepsilon = 10^{-4}$ and
$\delta = 0.008$.

\section{Chordal geometry of a correlation cap}

\begin{theorem}[Chordal identity]\label{thm:chordid}
For nonzero $u,v \in \R^n$, $\chord(u,v)^2 = 2 - 2\corr(u,v)$.
\end{theorem}

\begin{proof}
Expand bilinearly: $\|\uh-\vh\|^2 = \langle\uh,\uh\rangle - 2\langle\uh,\vh\rangle +
\langle\vh,\vh\rangle$. Since $u,v \ne 0$ the outer terms equal $1$, and the middle inner product is
$\corr(u,v)$ by scale-invariance.
\end{proof}

\begin{corollary}
$\chord(u,v) = \sqrt{2-2\corr(u,v)}$.
\end{corollary}

\begin{theorem}[Cap bound]\label{thm:cap}
If $\corr(u,v) \ge 1-\varepsilon$ then $\chord(u,v) \le \sqrt{2\varepsilon}$.
\end{theorem}

\begin{proof}
Monotonicity of the square root applied to $2-2\corr(u,v) \le 2\varepsilon$.
\end{proof}

\begin{theorem}[Angular form]\label{thm:angular}
For $c \in [-1,1]$, $\arccos c \le \tfrac{\pi}{2}\sqrt{2-2c}$.
\end{theorem}

\begin{proof}
Put $t = \arccos c \in [0,\pi]$, so $\cos t = c$. The half-angle identity $\cos t = 1-2\sin^2(t/2)$
gives $2-2c = 4\sin^2(t/2)$, and $\sin(t/2) \ge 0$ since $t/2 \in [0,\pi/2]$; hence $\sqrt{2-2c} =
2\sin(t/2)$. Jordan's inequality $\sin x \ge (2/\pi)x$ on $[0,\pi/2]$ at $x=t/2$ gives
$t \le \pi\sin(t/2) = (\pi/2)\sqrt{2-2c}$.
\end{proof}

\begin{theorem}[Cap radius of (R)]\label{thm:capR}
With $\varepsilon = 10^{-4}$ we have $\sqrt{2\varepsilon} = \sqrt2/100 = 0.0141421\ldots$ and
$\arccos(0.9999) < \pi/200 = 0.9^\circ$.
\end{theorem}

\begin{proof}
The first is $(\sqrt2/100)^2 = 2\cdot10^{-4}$. For the second set $x = \pi/400$ and use
$\sin x > x - x^3/4$ with $3 < \pi \le 4$ to get $\sin x > 0.0074$; then
$\cos(\pi/200) = 1-2\sin^2 x < 0.9999$, and strict antitonicity of $\arccos$ inverts the inequality.
\end{proof}

Numerically $\arccos(0.9999) = 0.0141423\ldots$ radians $=0.81027^\circ$. The whole hypothesis test
of (R) lives in a cap of angular radius below one degree.

\section{The Lipschitz power ceiling}

\begin{theorem}[Ceiling, chordal form]\label{thm:ceilchord}
If $F$ is $L$-Lipschitz on the sphere and $u,v$ are nonzero, then
$|F(\uh)-F(\vh)| \le L\,\chord(u,v)$.
\end{theorem}

\begin{proof}
$\uh,\vh$ are unit vectors, so the hypothesis applies with $\|\uh-\vh\| = \chord(u,v)$.
\end{proof}

\begin{theorem}[Spherical-Cap Power Ceiling]\label{thm:ceiling}
Let $L \ge 0$, let $F$ be $L$-Lipschitz on the sphere, and let $u,v \in \R^n$ be nonzero with
$\corr(u,v) \ge 1-\varepsilon$. Then
\[
|F(\uh)-F(\vh)| \;\le\; L\sqrt{2\varepsilon}.
\]
The bound is independent of $n$.
\end{theorem}

\begin{proof}
Chain Theorem~\ref{thm:ceilchord} with Theorem~\ref{thm:cap}, using $L \ge 0$.
\end{proof}

The absence of $n$ is the point: the bound does not degrade slowly with sample size, it does not
see the sample size at all.

\begin{theorem}[Converse: separation costs sensitivity]\label{thm:converse}
Under the hypotheses of Theorem~\ref{thm:ceiling} with $\varepsilon>0$, if $|F(\uh)-F(\vh)| \ge
\delta$ then $L \ge \delta/\sqrt{2\varepsilon}$.
\end{theorem}

\begin{corollary}[Full separation at (R) needs $L \ge 70$]
If $\corr(u,v) \ge 0.9999$ and an $L$-Lipschitz-on-the-sphere statistic achieves separation at least
$1$, then $L \ge 100/\sqrt2 = 70.71\ldots$, in particular $L \ge 70$.
\end{corollary}

Such a statistic moves by more than seventy units per unit of movement on the sphere: it measures
the position of the decision boundary, not the effect.

\section{Replication leaves the cap invariant}

\begin{lemma}\label{lem:rep}
$\langle \rep_m u, \rep_m v\rangle = m\langle u,v\rangle$ and $\|\rep_m u\| = \sqrt m\,\|u\|$.
\end{lemma}

\begin{proof}
Re-index the sum over $\{1,\dots,mn\}$ as one over $\{1,\dots,m\}\times\{1,\dots,n\}$ whose summand
does not depend on the first factor; the inner sum is $\langle u,v\rangle$ and there are $m$ of them.
\end{proof}

\begin{theorem}[Replication invariance]\label{thm:repinv}
For $m \ge 1$ and nonzero $u,v$, $\corr(\rep_m u, \rep_m v) = \corr(u,v)$, and consequently
$\chord(\rep_m u, \rep_m v) = \chord(u,v)$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:rep} the numerator gains a factor $m$ and the denominator gains
$\sqrt m\cdot\sqrt m = m$; these cancel. The chord claim follows from Theorem~\ref{thm:chordid}.
\end{proof}

\begin{theorem}[Replication does not help]
For every $m\ge1$ the $m$-fold replication of the (R) predictors gives nonzero $u_m,v_m \in
\R^{2m}$ with $\corr(u_m,v_m) \ge 0.9999$ and $|F(\hat u_m)-F(\hat v_m)| \le L\sqrt2/100$ for every
$L \ge 0$ and every $F$ that is $L$-Lipschitz on the sphere of $\R^{2m}$.
\end{theorem}

\begin{proof}
Replicate (R), transport the alignment hypothesis by Theorem~\ref{thm:repinv}, and apply
Theorem~\ref{thm:ceiling} in dimension $2m$ with $\varepsilon = 10^{-4}$, using
Theorem~\ref{thm:capR}.
\end{proof}

The ceiling constant is literally the same real number for every $m$.

\section{Sharpness and non-vacuity}

\begin{theorem}[Sharpness]\label{thm:sharp}
For every $L \ge 0$ and all nonzero $u,v$ there is an $L$-Lipschitz statistic $F$ with
$|F(\uh)-F(\vh)| = L\,\chord(u,v)$.
\end{theorem}

\begin{proof}
Take $F(x) = L\|x-\vh\|$. The reverse triangle inequality gives $|F(x)-F(y)| \le L\|x-y\|$; and
$F(\vh) = 0$, $F(\uh) = L\|\uh-\vh\|$.
\end{proof}

\begin{theorem}[Correlation is $1$-Lipschitz on the sphere]\label{thm:corrlip}
Let $\|w\| = 1$. Then $F(x) = \corr(x,w)$ satisfies $|F(x)-F(y)| \le \|x-y\|$ for all unit $x,y$.
\end{theorem}

\begin{proof}
For unit $x$ and $w$, $\corr(x,w) = \langle x,w\rangle$, so $|F(x)-F(y)| = |\langle x-y,w\rangle|
\le \|x-y\|$ by Cauchy--Schwarz.
\end{proof}

\begin{remark}
$x \mapsto \corr(x,w)$ is not globally Lipschitz on $\R^n$ (its slope blows up near the origin),
which is exactly why the sphere-restricted class is the correct hypothesis: it is what the geometry
uses and what the practitioner's statistic satisfies.
\end{remark}

\begin{proposition}[Chordal pseudometric]
$\chord(u,v) = \chord(v,u)$, $\chord(u,u) = 0$, and $\chord(u,w) \le \chord(u,v)+\chord(v,w)$, the
last by Minkowski applied to $\uh-\hat w = (\uh-\vh)+(\vh-\hat w)$.
\end{proposition}

\section{The alignment window}

\begin{theorem}[A reading gap forces a chordal separation]\label{thm:gap}
For nonzero $u,v,w$, $\;|\corr(u,w)-\corr(v,w)| \le \chord(u,v)$.
\end{theorem}

\begin{proof}
Normalise $w$; by Theorem~\ref{thm:corrlip} the map $x \mapsto \corr(x,\hat w)$ is $1$-Lipschitz on
the sphere, so evaluating at the unit vectors $\uh,\vh$ gives the claim, correlations being
unchanged by normalising either argument.
\end{proof}

\begin{theorem}[A margin caps the alignment]\label{thm:margin}
If $\corr(u,w)-\corr(v,w) \ge \delta \ge 0$ then $\corr(u,v) \le 1-\delta^2/2$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:gap} gives $\delta \le \chord(u,v)$; square and apply Theorem~\ref{thm:chordid}.
\end{proof}

\begin{theorem}[The (R) alignment window]
Both hold: (i) there exist nonzero $u,v,w \in \R^2$ realising $\corr(u,w) = 0.558$,
$\corr(v,w) = 0.550$ with $\corr(u,v) \ge 0.9999$; and (ii) for every $n$ and all nonzero
$u,v,w\in\R^n$ realising those two readings, $\corr(u,v) \le 1-3.2\times10^{-5} = 0.999968$.
\end{theorem}

\begin{proof}
(i) is Configuration~\ref{cfg:R}; (ii) is Theorem~\ref{thm:margin} with $\delta = 0.008$.
\end{proof}

The alignment is thus pinned inside a window of width $6.8\times10^{-5}$:
\[
0.9999 \;\le\; \corr(u,v) \;\le\; 0.999968 .
\]

\begin{corollary}[The recorded test is already near-optimal]
On (R) the response-correlation statistic separates the hypotheses by exactly $0.008$, while every
$1$-Lipschitz-on-the-sphere statistic is capped at $\sqrt2/100 = 0.014142\ldots$. The recorded test
achieves $56.6\%$ of the theoretical maximum, and no smooth test improves on it by more than the
factor $1.7678$.
\end{corollary}

\section{The optimal smooth test}

\begin{lemma}
If $\uh \ne \vh$ then $e = (\uh-\vh)/\|\uh-\vh\|$ is a unit vector.
\end{lemma}

\begin{theorem}[The contrast test attains the chord]\label{thm:contrast}
Let $u,v$ be nonzero with $\uh \ne \vh$ and $e = (\uh-\vh)/\|\uh-\vh\|$. Then
\[
\corr(\uh,e) - \corr(\vh,e) \;=\; \chord(u,v).
\]
\end{theorem}

\begin{proof}
All three vectors are unit, so correlations against $e$ are inner products, and
\[
\langle \uh - \vh, e\rangle = \frac{\langle \uh-\vh,\uh-\vh\rangle}{\|\uh-\vh\|}
= \frac{\|\uh-\vh\|^2}{\|\uh-\vh\|} = \|\uh-\vh\| . \qedhere
\]
\end{proof}

\begin{theorem}[The smooth optimum is exactly the chordal distance]\label{thm:optimum}
Let $u,v$ be nonzero with $\uh\ne\vh$. Then there is a unit vector $e$ with
$|\corr(\uh,e)-\corr(\vh,e)| = \chord(u,v)$, and every $F$ that is $1$-Lipschitz on the sphere
satisfies $|F(\uh)-F(\vh)| \le \chord(u,v)$. Hence
\[
\max\bigl\{\,|F(\uh)-F(\vh)| : F \text{ is } 1\text{-Lipschitz on the sphere}\,\bigr\} = \chord(u,v),
\]
attained by a correlation statistic.
\end{theorem}

\begin{proof}
Existence is Theorem~\ref{thm:contrast} together with Theorem~\ref{thm:corrlip} (which places the
statistic in the class); the upper bound is Theorem~\ref{thm:ceilchord} with $L=1$.
\end{proof}

\begin{theorem}[The optimal smooth test at (R)]
There exist nonzero $u,v,w\in\R^2$ with $\corr(u,w)=0.558$, $\corr(v,w)=0.550$, and a unit vector
$e$ with $\corr(\uh,e)-\corr(\vh,e) = \chord(u,v)$ and
\[
0.008 \;\le\; \chord(u,v) \;\le\; \frac{\sqrt2}{100},
\]
such that no statistic $1$-Lipschitz on the sphere separates $\uh,\vh$ by more than $\chord(u,v)$.
\end{theorem}

\begin{proof}
Take (R) and $e = (\uh-\vh)/\|\uh-\vh\|$. The lower bound is Theorem~\ref{thm:gap} applied to the
recorded margin (which also certifies $\uh \ne \vh$); the upper bound is Theorem~\ref{thm:cap} with
$\varepsilon = 10^{-4}$; optimality is Theorem~\ref{thm:optimum}.
\end{proof}

\begin{theorem}[The contrast test dominates the recorded test, by at most $1.7678$]
On (R), with $e$ the contrast direction,
\[
|\corr(\uh,w)-\corr(\vh,w)| = 0.008 \;\le\; |\corr(\uh,e)-\corr(\vh,e)| \;\le\; 1.7678 \times 0.008 .
\]
\end{theorem}

There is a strictly better smooth test than the recorded one, it is easy to describe, and it is
optimal in its class --- and it buys at most a factor $1.77$ on a gap of $0.008$. Optimising within
the smooth class is not where the leverage is.

\section{Cap capacity and H\"older robustness}

\begin{theorem}[Chain bound]
Let $f_0,\dots,f_k$ be nonzero with $\corr(f_i,f_{i+1}) \ge 1-\varepsilon$ for all $i<k$. Then
$\chord(f_0,f_k) \le k\sqrt{2\varepsilon}$; and if $F$ is $L$-Lipschitz on the sphere with $L\ge0$,
$|F(\hat f_0)-F(\hat f_k)| \le kL\sqrt{2\varepsilon}$.
\end{theorem}

\begin{proof}
Induction on $k$, the base case being $\chord(f_0,f_0)=0$ and the step combining the triangle
inequality with Theorem~\ref{thm:cap}; then apply Theorem~\ref{thm:ceilchord}.
\end{proof}

\begin{theorem}[Cap capacity bound]\label{thm:capacity}
Let $F$ be $L$-Lipschitz on the sphere with $L \ge 0$, let $f_0,\dots,f_k$ be nonzero with
$F(\hat f_{i+1}) - F(\hat f_i) \ge \delta$ for all $i<k$, and suppose $\corr(f_0,f_k) \ge
1-\varepsilon$. Then $k\delta \le L\sqrt{2\varepsilon}$.
\end{theorem}

\begin{proof}
Telescoping gives $F(\hat f_k)-F(\hat f_0) \ge k\delta$; the ceiling
(Theorem~\ref{thm:ceiling}) bounds the same difference by $L\sqrt{2\varepsilon}$.
\end{proof}

\begin{corollary}
With $L=1$, $\delta = 0.008$, $\varepsilon = 10^{-4}$: $k \le 1.7678$, hence $k \le 1$. The (R) cap
holds at most one resolvable rung.
\end{corollary}

\begin{theorem}[One rung is resolvable: the capacity bound is tight]
There exist a statistic $F$ that is $1$-Lipschitz on the sphere and nonzero $f_0,f_1$ with
$F(\hat f_1)-F(\hat f_0) \ge 0.008$ and $\corr(f_0,f_1) \ge 0.9999$.
\end{theorem}

\begin{proof}
Take $F(x) = \corr(x,\hat w)$ from (R), which is $1$-Lipschitz on the sphere by
Theorem~\ref{thm:corrlip}, with $f_0 = v$, $f_1 = u$: the gain is exactly $0.558-0.550 = 0.008$ and
the alignment is the recorded one.
\end{proof}

\begin{theorem}[H\"older ceiling]
Let $C,\alpha \ge 0$ and let $F$ be $(C,\alpha)$-H\"older on the sphere. If $\corr(u,v) \ge
1-\varepsilon$ then $|F(\uh)-F(\vh)| \le C(\sqrt{2\varepsilon})^\alpha$; consequently a separation
$\delta$ requires $C \ge \delta/(\sqrt{2\varepsilon})^{\alpha}$.
\end{theorem}

At (R), full separation requires $C \ge 8.41$ at $\alpha = 1/2$ and $C \ge 70.71$ at $\alpha = 1$.
Lower exponents buy a milder constant only by making the statistic more singular at small scales:
resolution inside the cap is always purchased with local instability.

\section{Escaping the ceiling: the discontinuous test}

\begin{theorem}[A threshold statistic fully separates (R)]
On (R), with $t = 0.554$, $\;\Thr_{w,t}(\uh) - \Thr_{w,t}(\vh) = 1$.
\end{theorem}

\begin{proof}
$\corr(\uh,w) = 0.558 \ge t$ and $\corr(\vh,w) = 0.550 < t$.
\end{proof}

\begin{theorem}[The threshold statistic is Lipschitz for no constant]
For every real $L$, the statistic $\Thr_{w,t}$ with $w = (1,0)$ and $t = 0.554$ fails to be
$L$-Lipschitz.
\end{theorem}

\begin{proof}
Write $s = \sqrt{1-t^2}$, $x = (t,s)$, a unit vector with $\corr(x,w) = t$, so $\Thr_{w,t}(x) = 1$.
For $0 < d < 2t$ put $y = (t-d,s)$. Since
$t^2\|y\|^2 - (t-d)^2 = (1-t^2)\,d\,(2t-d) > 0$, we get $\corr(y,w) = (t-d)/\|y\| < t$ and hence
$\Thr_{w,t}(y) = 0$, while $\|x-y\| = d$. Choosing $d < \min\{t/2,\,1/(2(|L|+1))\}$ makes
$L\|x-y\| < 1 = |\Thr_{w,t}(x)-\Thr_{w,t}(y)|$, contradicting the Lipschitz inequality.
\end{proof}

The ceiling is therefore not a statement that the hypotheses are unresolvable, but that they are
unresolvable \emph{by stable statistics}.

